date_changed: "AUDIT_DUE_DATE_CHANGED", audit_assignee_added: "AUDIT_ASSIGNEE_ADDED", audit_assignee_removed: "AUDIT_ASSIGNEE_REMOVED", audit_updated: "AUDIT_UPDATED", audit_completed: "AUDIT_COMPLETED", audit_cancelled: "AUDIT_CANCELLED", audit_archived: "AUDIT_ARCHIVED", location_created: "LOCATION_CREATED", location_updated: "LOCATION_UPDATED", kit_created: "KIT_CREATED", kit_updated: "KIT_UPDATED", organization_qr_id_display_preference_changed: "ORGANIZATION_QR_ID_DISPLAY_PREFERENCE_CHANGED" },
